import { randomUUID } from 'crypto';
import { z } from 'zod';
import { isPidAlive } from '../utils/pid';
import { CoordinatorRecords } from '../storage/library/CoordinatorRecords';

const HubRecordSchema = z.object({
  pid: z.number().int().positive(),
  token: z.string().uuid(),
  port: z.number().int().positive().nullable(),
});
export type HubRecord = z.infer<typeof HubRecordSchema>;
type ClaimResult =
  | { status: 'owned'; token: string }
  | { status: 'occupied'; record: HubRecord };
export class HubDiscovery {
  private constructor(private readonly records: CoordinatorRecords) {}

  static async open(root: string): Promise<HubDiscovery> {
    return new HubDiscovery(await CoordinatorRecords.open(root));
  }

  read(): HubRecord | null {
    const row = this.records.read();
    return row ? HubRecordSchema.parse(row) : null;
  }

  claim(): ClaimResult {
    return this.records.transaction(() => {
      const record = this.read();
      if (record && isPidAlive(record.pid))
        return { status: 'occupied', record };
      const token = randomUUID();
      this.records.assign({ pid: process.pid, token, port: null });
      return { status: 'owned', token };
    });
  }

  publish({ token, port }: { token: string; port: number }): void {
    if (!this.records.publish({ pid: process.pid, token, port }))
      throw new Error('Coordinator ownership changed before startup completed');
  }

  release(token: string): void {
    this.records.release({ pid: process.pid, token });
  }

  discard(record: HubRecord): boolean {
    return this.records.discard(record);
  }

  close(): void {
    this.records.close();
  }
}
